Here is a complete, working implementation using **Node.js** and **Express**. 

It provides an upload form where you set a password, generates a unique download link, and prompts the recipient for the password before allowing the download.

---

### Step 1: Initialize the Project

Create a new directory and install the necessary dependencies:

```bash
mkdir secure-file-share
cd secure-file-share
npm init -y
npm install express multer bcrypt
```

---

### Step 2: Create the Backend (`server.js`)

Create a file named `server.js` and paste the following code:

```javascript
const express = require('express');
const multer = require('multer');
const bcrypt = require('bcrypt');
const crypto = require('crypto');
const path = require('path');
const fs = require('fs');

const app = express();
const PORT = 3000;

// Middleware
app.use(express.urlencoded({ extended: true }));
app.use(express.json());
app.use(express.static('public'));

// Ensure uploads folder exists
const uploadDir = path.join(__dirname, 'uploads');
if (!fs.existsSync(uploadDir)) {
  fs.mkdirSync(uploadDir);
}

// Multer storage configuration
const storage = multer.diskStorage({
  destination: (req, file, cb) => cb(null, 'uploads/'),
  filename: (req, file, cb) => {
    // Unique filename to prevent overwrites
    const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
    cb(null, uniqueSuffix + path.extname(file.originalname));
  }
});
const upload = multer({ storage });

// In-memory file database (for production, replace with a database like SQLite or MongoDB)
const fileDB = new Map();

// 1. Upload Route
app.post('/upload', upload.single('file'), async (req, res) => {
  try {
    if (!req.file || !req.body.password) {
      return res.status(400).send('File and password are required.');
    }

    const fileId = crypto.randomBytes(6).toString('hex'); // 12-char unique ID
    const hashedPassword = await bcrypt.hash(req.body.password, 10);

    fileDB.set(fileId, {
      id: fileId,
      originalName: req.file.originalname,
      storagePath: req.file.path,
      passwordHash: hashedPassword,
    });

    const shareUrl = `${req.protocol}://${req.get('host')}/file/${fileId}`;
    res.send(`
      <body style="font-family: sans-serif; display: flex; justify-content: center; align-items: center; height: 90vh;">
        <div style="border: 1px solid #ccc; padding: 24px; border-radius: 8px;">
          <h3>File uploaded successfully!</h3>
          <p>Share this link with your friends:</p>
          <input type="text" value="${shareUrl}" style="width: 100%; padding: 8px;" readonly onclick="this.select()" />
          <br><br>
          <a href="/">Upload another file</a>
        </div>
      </body>
    `);
  } catch (err) {
    res.status(500).send('Error uploading file.');
  }
});

// 2. Access Shared Link Route
app.get('/file/:id', (req, res) => {
  const fileData = fileDB.get(req.params.id);

  if (!fileData) {
    return res.status(404).send('File not found or link expired.');
  }

  // Password entry form
  res.send(`
    <!DOCTYPE html>
    <html>
    <head>
      <title>Download Protected File</title>
      <style>
        body { font-family: sans-serif; display: flex; justify-content: center; align-items: center; height: 90vh; }
        .box { border: 1px solid #ccc; padding: 24px; border-radius: 8px; width: 300px; text-align: center; }
        input { width: 90%; padding: 8px; margin: 10px 0; }
        button { padding: 10px 20px; background: #007bff; color: white; border: none; border-radius: 4px; cursor: pointer; }
      </style>
    </head>
    <body>
      <div class="box">
        <h3>Protected File</h3>
        <p>File: <strong>${fileData.originalName}</strong></p>
        <form action="/download/${req.params.id}" method="POST">
          <input type="password" name="password" placeholder="Enter password" required />
          <button type="submit">Download</button>
        </form>
      </div>
    </body>
    </html>
  `);
});

// 3. Verification & Download Route
app.post('/download/:id', async (req, res) => {
  const fileData = fileDB.get(req.params.id);

  if (!fileData) {
    return res.status(404).send('File not found.');
  }

  const isMatch = await bcrypt.compare(req.body.password, fileData.passwordHash);

  if (!isMatch) {
    return res.status(403).send('Incorrect password. <a href="javascript:history.back()">Try again</a>');
  }

  // Serve the file with its original name
  res.download(path.resolve(fileData.storagePath), fileData.originalName);
});

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

---

### Step 3: Create the Frontend (`public/index.html`)

Create a folder named `public` and add an `index.html` file inside it:

```bash
mkdir public
```

Inside `public/index.html`:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Password Protected File Upload</title>
  <style>
    body {
      font-family: sans-serif;
      display: flex;
      justify-content: center;
      align-items: center;
      height: 90vh;
      background: #f4f6f8;
    }
    .card {
      background: white;
      padding: 30px;
      border-radius: 8px;
      box-shadow: 0 4px 6px rgba(0,0,0,0.1);
      width: 320px;
    }
    .field {
      margin-bottom: 15px;
    }
    label {
      display: block;
      margin-bottom: 5px;
      font-weight: bold;
      font-size: 14px;
    }
    input {
      width: 100%;
      padding: 8px;
      box-sizing: border-box;
      border: 1px solid #ccc;
      border-radius: 4px;
    }
    button {
      width: 100%;
      padding: 10px;
      background: #28a745;
      color: white;
      border: none;
      border-radius: 4px;
      font-size: 16px;
      cursor: pointer;
    }
    button:hover {
      background: #218838;
    }
  </style>
</head>
<body>

  <div class="card">
    <h2>Share a File</h2>
    <form action="/upload" method="POST" enctype="multipart/form-data">
      <div class="field">
        <label>Choose File</label>
        <input type="file" name="file" required />
      </div>
      <div class="field">
        <label>Set Password</label>
        <input type="password" name="password" placeholder="Choose a password" required />
      </div>
      <button type="submit">Upload & Get Link</button>
    </form>
  </div>

</body>
</html>
```

---

### Step 4: Run the Application

Run the server:

```bash
node server.js
```

1. Open your browser to `http://localhost:3000`.
2. Choose a file, enter a password, and click **Upload & Get Link**.
3. Copy the generated link (e.g., `http://localhost:3000/file/a1b2c3d4e5f6`) and open it in an Incognito window.
4. Enter the password you set to download the file.

